static void shuffle(char *text) {
    int n = (int)strlen(text);
    for (int i = n - 1; i > 0; i--) {
        int j = rand() % (i + 1);
        char tmp = text[i];
        text[i] = text[j];
        text[j] = tmp;
    }
}

char *generate_random_password(int length) {
    if (length < 1) {
        fprintf(stderr, "length must be greater than 0\n");
        return NULL;
    }
